{
  "name": "AI-Powered Support Flow",
  "triggerType": "keyword",
  "triggerConfig": {
    "keywords": ["help", "support", "issue", "problem"],
    "matchMode": "contains"
  },
  "description": "Automated support with AI chatbot integration"
}

{
  "name": "AI-Powered Support Flow",
  "nodes": [
    {
      "id": "trigger-1",
      "type": "trigger",
      "position": { "x": 250, "y": 50 },
      "data": {
        "label": "Support Trigger",
        "keywords": ["help", "support", "issue", "problem"],
        "matchMode": "contains"
      }
    },
    {
      "id": "understand-1",
      "type": "webhookCall",
      "position": { "x": 250, "y": 200 },
      "data": {
        "label": "Analyze with AI",
        "url": "http://localhost:3000/api/ai-chatbot/understand",
        "method": "POST",
        "headers": {
          "Authorization": "Bearer {{ai_token}}",
          "Content-Type": "application/json"
        },
        "body": "{\"message\": \"{{message}}\"}",
        "saveResponseAs": "analysis"
      }
    },
    {
      "id": "condition-1",
      "type": "condition",
      "position": { "x": 250, "y": 380 },
      "data": {
        "label": "Sentiment Check",
        "field": "analysis.sentiment",
        "operator": "equals",
        "value": "negative"
      }
    },
    {
      "id": "ai-reply-1",
      "type": "webhookCall",
      "position": { "x": 100, "y": 560 },
      "data": {
        "label": "Generate AI Reply",
        "url": "http://localhost:3000/api/ai-chatbot/auto-reply",
        "method": "POST",
        "headers": {
          "Authorization": "Bearer {{ai_token}}",
          "Content-Type": "application/json"
        },
        "body": "{\"message\": \"{{message}}\", \"contactId\": \"{{contact.phone}}\"}",
        "saveResponseAs": "aiResponse"
      }
    },
    {
      "id": "send-ai-1",
      "type": "sendMessage",
      "position": { "x": 100, "y": 730 },
      "data": {
        "label": "Send AI Reply",
        "message": "{{aiResponse.reply}}"
      }
    },
    {
      "id": "assign-1",
      "type": "assignAgent",
      "position": { "x": 100, "y": 900 },
      "data": {
        "label": "Escalate to Agent",
        "team": "support-team",
        "priority": "high"
      }
    },
    {
      "id": "suggest-1",
      "type": "webhookCall",
      "position": { "x": 400, "y": 560 },
      "data": {
        "label": "Get Suggestions",
        "url": "http://localhost:3000/api/ai-chatbot/suggest-replies",
        "method": "POST",
        "headers": {
          "Authorization": "Bearer {{ai_token}}",
          "Content-Type": "application/json"
        },
        "body": "{\"customerMessage\": \"{{message}}\"}",
        "saveResponseAs": "suggestions"
      }
    },
    {
      "id": "send-suggestions-1",
      "type": "sendButtons",
      "position": { "x": 400, "y": 730 },
      "data": {
        "label": "Send Suggestions",
        "message": "Here are some suggested responses:",
        "buttons": [
          { "id": "btn1", "text": "{{suggestions.suggestions[0]}}" },
          { "id": "btn2", "text": "{{suggestions.suggestions[1]}}" },
          { "id": "btn3", "text": "{{suggestions.suggestions[2]}}" }
        ]
      }
    },
    {
      "id": "tag-1",
      "type": "addTag",
      "position": { "x": 250, "y": 1050 },
      "data": {
        "label": "Tag as Supported",
        "tagName": "ai-supported"
      }
    },
    {
      "id": "end-1",
      "type": "end",
      "position": { "x": 250, "y": 1200 },
      "data": { "label": "End" }
    }
  ],
  "edges": [
    { "id": "e1", "source": "trigger-1", "target": "understand-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e2", "source": "understand-1", "target": "condition-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e3", "source": "condition-1", "target": "ai-reply-1", "sourceHandle": "yes", "targetHandle": null, "type": "default", "data": {}, "label": "Negative", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e4", "source": "condition-1", "target": "suggest-1", "sourceHandle": "no", "targetHandle": null, "type": "default", "data": {}, "label": "Positive/Neutral", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e5", "source": "ai-reply-1", "target": "send-ai-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e6", "source": "send-ai-1", "target": "assign-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e7", "source": "suggest-1", "target": "send-suggestions-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e8", "source": "assign-1", "target": "tag-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e9", "source": "send-suggestions-1", "target": "tag-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false },
    { "id": "e10", "source": "tag-1", "target": "end-1", "sourceHandle": null, "targetHandle": null, "type": "default", "data": {}, "label": "", "markerEnd": "arrowclosed", "style": { "strokeWidth": 2 }, "animated": false }
  ]
}

